-- Bounded detail pages plus aggregates over the complete RLS-authorized dataset.
-- Owner IDs are resolved by the existing API directory scope, then passed as a
-- bound uuid[]; no table/column identifiers come from the request.
create function public.report_page_metrics(
  report_input text, from_input timestamptz default null, to_input timestamptz default null,
  owner_ids_input uuid[] default null, page_input integer default 1, search_input text default ''
) returns jsonb language plpgsql security invoker set search_path = '' as $function$
declare result jsonb;
begin
  if not public.has_permission('report.view') then raise exception using errcode='42501',message='REPORT_FORBIDDEN'; end if;
  if report_input not in ('service-desk','requests-workflows','assets-operations','asset-custody','asset-verification','security-resilience','governance-compliance')
    or page_input not between 1 and 1000000 or length(search_input)>200 then raise exception 'REPORT_PAGE_INVALID'; end if;
  execute $query$
    with raw as (select 'service-desk'::text report_key,'tickets'::text table_key,t.id,'Ticket'::text source,coalesce((t.ticket_no)::text,'') as code,coalesce((t.title)::text,'') title,coalesce((t.status)::text,'—') status,coalesce(nullif((coalesce(c.name,t.priority))::text,''),'—') category,t.assignee_id as owner_id,coalesce(nullif((t.assignee_name_snapshot)::text,''),(t.assignee_id)::text,'—') as owner_name,(t.due_at)::timestamptz due_at,(t.created_at)::timestamptz created_at,(coalesce(t.closed_at,t.resolved_at))::timestamptz completed_at,coalesce(((t.status) ~* 'ปิด|เสร็จ|สำเร็จ|อนุมัติแล้ว|ยกเลิก|ปฏิเสธ|ผ่าน|inactive|expired|closed|completed|cancelled'),false) terminal,(t.sla_paused_at is not null) paused,coalesce((false),false) warning,coalesce((t.priority='วิกฤต'),false) critical,coalesce((0)::numeric,0) amount,(t.rating)::numeric rating,(t.feedback)::text feedback,(t.feedback_at)::timestamptz feedback_at from public.tickets t left join public.ticket_categories c on c.id=t.category_id where (select public.has_permission('ticket.view')) and ($1 is null or (t.created_at) >= $1) and ($2 is null or (t.created_at) < $2) and ($3 is null or (t.assignee_id) = any($3))
union all
select 'requests-workflows'::text report_key,'service_requests'::text table_key,t.id,'Service Request'::text source,coalesce((t.service_code)::text,'') as code,coalesce((coalesce(nullif(t.summary,''),t.service_name))::text,'') title,coalesce((t.status)::text,'—') status,coalesce(nullif((t.priority)::text,''),'—') category,t.assignee_id as owner_id,coalesce(nullif((null::text)::text,''),(t.assignee_id)::text,'—') as owner_name,(t.due_at)::timestamptz due_at,(t.created_at)::timestamptz created_at,(coalesce(t.closed_at,t.completed_at))::timestamptz completed_at,coalesce(((t.status) ~* 'ปิด|เสร็จ|สำเร็จ|อนุมัติแล้ว|ยกเลิก|ปฏิเสธ|ผ่าน|inactive|expired|closed|completed|cancelled'),false) terminal,(false) paused,coalesce((false),false) warning,coalesce((false),false) critical,coalesce((0)::numeric,0) amount,(null::numeric)::numeric rating,(null::text)::text feedback,(null::timestamptz)::timestamptz feedback_at from public.service_requests t  where (select public.has_permission('service_request.view')) and ($1 is null or (t.created_at) >= $1) and ($2 is null or (t.created_at) < $2) and ($3 is null or (t.assignee_id) = any($3))
union all
select 'requests-workflows'::text report_key,'access_requests'::text table_key,t.id,'Access Request'::text source,coalesce((upper(left(t.id::text,8)))::text,'') as code,coalesce((t.request_type || ' · ' || coalesce(upper(i.kind) || ' · ' || i.name,t.access_level))::text,'') title,coalesce((t.status)::text,'—') status,coalesce(nullif((coalesce(upper(i.kind) || ' · ' || i.name,t.access_level))::text,''),'—') category,t.it_handler_id as owner_id,coalesce(nullif((null::text)::text,''),(t.it_handler_id)::text,'—') as owner_name,(t.review_due::timestamptz)::timestamptz due_at,(t.created_at)::timestamptz created_at,(t.it_action_at)::timestamptz completed_at,coalesce(((t.status) ~* 'ปิด|เสร็จ|สำเร็จ|อนุมัติแล้ว|ยกเลิก|ปฏิเสธ|ผ่าน|inactive|expired|closed|completed|cancelled'),false) terminal,(false) paused,coalesce((false),false) warning,coalesce((false),false) critical,coalesce((0)::numeric,0) amount,(null::numeric)::numeric rating,(null::text)::text feedback,(null::timestamptz)::timestamptz feedback_at from public.access_requests t left join public.access_control_items i on i.id=t.access_item_id where (select public.has_permission('access_request.view')) and ($1 is null or (t.created_at) >= $1) and ($2 is null or (t.created_at) < $2) and ($3 is null or (t.it_handler_id) = any($3))
union all
