select 'governance-compliance'::text report_key,'governance_evidence_items'::text table_key,t.id,'Evidence'::text source,coalesce((t.evidence_code)::text,'') as code,coalesce((t.title)::text,'') title,coalesce((t.status)::text,'—') status,coalesce(nullif((t.source_module)::text,''),'—') category,null::uuid as owner_id,coalesce(nullif((t.owner)::text,''),(null::uuid)::text,'—') as owner_name,(t.expires_at)::timestamptz due_at,(coalesce(t.observed_at,t.created_at))::timestamptz created_at,(null::timestamptz)::timestamptz completed_at,coalesce(((t.status) ~* 'ปิด|เสร็จ|สำเร็จ|อนุมัติแล้ว|ยกเลิก|ปฏิเสธ|ผ่าน|inactive|expired|closed|completed|cancelled'),false) terminal,(false) paused,coalesce((t.expires_at < now()),false) warning,coalesce((false),false) critical,coalesce((0)::numeric,0) amount,(null::numeric)::numeric rating,(null::text)::text feedback,(null::timestamptz)::timestamptz feedback_at from public.governance_evidence_items t  where (select public.has_permission('evidence.view')) and true and ($3 is null or (null::uuid) = any($3))),
    entries as (
      select *, due_at < now() and not terminal and not paused as overdue from raw where report_key = $4
    ), filtered as (
      select * from entries where $5 = '' or strpos(lower(concat_ws(' ',source,code,title,status,category,owner_name)),lower($5)) > 0
    ), page as (
      select table_key,id from filtered order by case when $4='asset-custody' then owner_id::text end,
        case when $4='asset-custody' then category end,created_at desc,table_key,id limit 25 offset $6
    ), stats as (
      select count(*) as total,count(*) filter(where not terminal) as open,count(*) filter(where terminal) as completed,
        count(*) filter(where overdue) as overdue,count(*) filter(where warning) as warning,
        count(*) filter(where critical and not terminal) as critical,count(*) filter(where paused) as paused,
        coalesce(sum(amount),0) as amount,count(rating) as rating_count,coalesce(sum(rating),0) as rating_sum,
        count(*) filter(where status='ครอบครอง') as held,count(distinct owner_id) filter(where status in ('ครอบครอง','ส่งซ่อม')) as holders
      from entries
    ), rated as (select * from entries where rating between 1 and 5)
    select jsonb_build_object(
      'page',coalesce((select jsonb_agg(jsonb_build_object('table',table_key,'id',id)) from page),'[]'::jsonb),
      'filteredTotal',(select count(*) from filtered),'stats',(select to_jsonb(stats) from stats),
      'sources',coalesce((select jsonb_agg(to_jsonb(s)) from (select source as label,count(*) as value from entries group by source order by count(*) desc,source) s),'[]'::jsonb),
      'statuses',coalesce((select jsonb_agg(to_jsonb(s)) from (select status as label,count(*) as value from entries group by status order by count(*) desc,status) s),'[]'::jsonb),
      'categories',coalesce((select jsonb_agg(to_jsonb(s)) from (select category as label,count(*) as value from entries group by category order by count(*) desc,category) s),'[]'::jsonb),
      'employeeCounts',case when $4='asset-custody' then coalesce((select jsonb_agg(to_jsonb(s)) from (select owner_id as id,count(*) as value from entries group by owner_id) s),'[]'::jsonb) else '[]'::jsonb end,
      'trend',coalesce((select jsonb_agg(jsonb_build_object('key',to_char(month,'YYYY-MM'),'primary',(select count(*) from entries where created_at at time zone 'UTC'>=month and created_at at time zone 'UTC'<month+interval '1 month'),'secondary',(select count(*) from entries where completed_at at time zone 'UTC'>=month and completed_at at time zone 'UTC'<month+interval '1 month'))) from generate_series(date_trunc('month',now() at time zone 'UTC')-interval '5 months',date_trunc('month',now() at time zone 'UTC'),interval '1 month') month),'[]'::jsonb),
      'csat',case when $4='service-desk' then jsonb_build_object(
        'average',(select round(avg(rating),2) from rated),'responseCount',(select count(*) from rated),
        'distribution',(select jsonb_agg(jsonb_build_object('score',score,'count',(select count(*) from rated where rating=score),'percentage',coalesce(round(100.0*(select count(*) from rated where rating=score)/nullif((select count(*) from rated),0),1),0))) from generate_series(5,1,-1) score),
        'weeklyTrend',coalesce((select jsonb_agg(jsonb_build_object('key',to_char(week,'YYYY-MM-DD'),'average',(select round(avg(rating),2) from rated where coalesce(feedback_at,created_at) at time zone 'UTC'>=week and coalesce(feedback_at,created_at) at time zone 'UTC'<week+interval '1 week'),'responses',(select count(*) from rated where coalesce(feedback_at,created_at) at time zone 'UTC'>=week and coalesce(feedback_at,created_at) at time zone 'UTC'<week+interval '1 week'))) from generate_series(date_trunc('week',now() at time zone 'UTC')-interval '11 weeks',date_trunc('week',now() at time zone 'UTC'),interval '1 week') week),'[]'::jsonb),
        'categories',coalesce((select jsonb_agg(to_jsonb(s)) from(select category as label,round(avg(rating),2) average,count(*) responses from rated where category<>'—' group by category order by avg(rating) desc,count(*) desc,category) s),'[]'::jsonb),
        'technicians',coalesce((select jsonb_agg(to_jsonb(s)) from(select owner_name as label,min(owner_id::text) as owner_id,round(avg(rating),2) average,count(*) responses from rated where owner_name<>'—' group by owner_name order by avg(rating) desc,count(*) desc,owner_name limit 5) s),'[]'::jsonb),
        'followUpCount',(select count(*) from rated where rating<=3),
        'followUps',coalesce((select jsonb_agg(to_jsonb(s)) from(select id,code,title,rating,coalesce(feedback,'') feedback,coalesce(feedback_at,created_at) as "submittedAt",owner_name as owner,owner_id from rated where rating<=3 order by coalesce(feedback_at,created_at) desc,id limit 20) s),'[]'::jsonb),
        'mentions',coalesce((select jsonb_agg(to_jsonb(s)) from(
          select word as label,count(*) as count from rated cross join lateral public.report_feedback_words(coalesce(feedback,'')) word
          where length(word)>=3 and word<>all(array['การ','และ','ที่','ได้','ให้','ของ','มาก','ครับ','ค่ะ','แต่','จาก','กับ','เป็น','ไม่','มี','แล้ว'])
          group by word order by count(*) desc,word limit 10) s),'[]'::jsonb)
      ) else null end)
  $query$ into result using from_input,to_input,owner_ids_input,report_input,search_input,(page_input::bigint-1)*25;
  return result;
end;
$function$;
revoke all on function public.report_page_metrics(text,timestamptz,timestamptz,uuid[],integer,text) from public, anon;
grant execute on function public.report_page_metrics(text,timestamptz,timestamptz,uuid[],integer,text) to authenticated;

create function public.report_owner_scope_ids(department_input uuid, owner_input uuid)
returns uuid[] language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(id),'{}'::uuid[]) from (
    select id from public.profiles where (department_input is not null or owner_input is not null)
      and (department_input is null or department_id = department_input) and (owner_input is null or id = owner_input)
    union
    select id from public.employees where (department_input is not null or owner_input is not null)
      and (department_input is null or department_id = department_input) and (owner_input is null or id = owner_input)
  ) owners;
$$;
revoke all on function public.report_owner_scope_ids(uuid,uuid) from public, anon, authenticated;
grant execute on function public.report_owner_scope_ids(uuid,uuid) to service_role;

